"""Generated by deploy/build_bundle.py from contracts/releases.py and contracts/pot.py.
Comments removed to keep the deploy small; read them in those files."""
PYPI = 'pypi'
NPM = 'npm'
REGISTRIES = (PYPI, NPM)
SHIPPED = 'shipped'
UNCLAIMED = 'unclaimed'
NOT_YET = 'not_yet'
UNKNOWN = 'unknown'
VERDICTS = (SHIPPED, UNCLAIMED, NOT_YET, UNKNOWN)
MIN_LEAD = 3600
MAX_LEAD = 366 * 24 * 3600
_MAX_NAME = 100

def normalise_package(registry: str, name: str) -> str:
    n = (name or '').strip()
    if registry == PYPI:
        out = []
        for ch in n.lower():
            if ch in '-_.':
                if not out or out[-1] != '-':
                    out.append('-')
            else:
                out.append(ch)
        return ''.join(out)
    return n.lower()

def valid_package(registry: str, name: str) -> bool:
    n = (name or '').strip()
    if not n or len(n) > _MAX_NAME:
        return False
    if registry == PYPI:
        if not (n[0].isalnum() and n[-1].isalnum() and n.isascii()):
            return False
        return all((ch.isalnum() or ch in '-_.' for ch in n))
    if registry == NPM:
        if n != n.lower() or not n.isascii():
            return False
        body = n
        if n.startswith('@'):
            if n.count('/') != 1:
                return False
            scope, body = n[1:].split('/')
            if not scope or not _npm_part(scope):
                return False
        elif '/' in n:
            return False
        return bool(body) and _npm_part(body) and (body[0] not in '._')
    return False

def _npm_part(part: str) -> bool:
    return all(('a' <= ch <= 'z' or '0' <= ch <= '9' or ch in '-._~' for ch in part))

def valid_version(version: str) -> bool:
    v = (version or '').strip()
    if not v or len(v) > 40 or (not v.isascii()):
        return False
    i = 0
    groups = 0
    while True:
        start = i
        while i < len(v) and v[i].isdigit():
            i += 1
        if i == start:
            return False
        groups += 1
        if i < len(v) and v[i] == '.' and (i + 1 < len(v)) and v[i + 1].isdigit():
            i += 1
            continue
        break
    if groups < 1 or groups > 4:
        return False
    tail = v[i:]
    if not tail:
        return True
    if tail[0] in '-.':
        tail = tail[1:]
    if not tail or not tail[0].isalpha():
        return False
    return all((ch.isalnum() or ch in '-.' for ch in tail)) and (not tail.endswith(('.', '-')))

def registry_url(registry: str, package: str, version: str) -> str:
    name = normalise_package(registry, package)
    v = version.strip()
    if registry == PYPI:
        return 'https://pypi.org/pypi/' + name + '/' + v + '/json'
    if registry == NPM:
        return 'https://registry.npmjs.org/' + name + '/' + v
    raise ValueError('unknown registry')

def names_version(body: str, version: str) -> bool:
    v = version.strip()
    text = body or ''
    return '"version":"' + v + '"' in text or '"version": "' + v + '"' in text

def names_payee(body: str, payee: str) -> bool:
    address = (payee or '').strip().lower()
    if len(address) != 42 or not address.startswith('0x'):
        return False
    return address in (body or '').lower()

def classify(status: int, body: str, version: str, payee: str) -> dict:
    code = int(status)
    if code == 200:
        if not names_version(body, version):
            return {'verdict': UNKNOWN, 'note': 'a 200 that did not name this version'}
        if names_payee(body, payee):
            return {'verdict': SHIPPED, 'note': 'the release names this payee'}
        return {'verdict': UNCLAIMED, 'note': 'the release does not name this payee'}
    if code == 404:
        return {'verdict': NOT_YET, 'note': 'the registry has no such version'}
    return {'verdict': UNKNOWN, 'note': 'the registry answered ' + str(code)}

def unreached() -> dict:
    return {'verdict': UNKNOWN, 'note': 'the registry could not be reached'}

def epoch_seconds(stamp: str):
    s = (stamp or '').strip()
    if len(s) < 19 or s[4] != '-' or s[7] != '-' or (s[10] != 'T') or (s[13] != ':') or (s[16] != ':'):
        return None
    for i in (0, 1, 2, 3, 5, 6, 8, 9, 11, 12, 14, 15, 17, 18):
        if not '0' <= s[i] <= '9':
            return None
    year, month, day = (int(s[0:4]), int(s[5:7]), int(s[8:10]))
    hour, minute, second = (int(s[11:13]), int(s[14:16]), int(s[17:19]))
    if not 1 <= month <= 12 or day < 1 or day > _days_in_month(year, month):
        return None
    if hour > 23 or minute > 59 or second > 60:
        return None
    return _days_from_civil(year, month, day) * 86400 + hour * 3600 + minute * 60 + second

def _days_in_month(year: int, month: int) -> int:
    if month == 2:
        leap = year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)
        return 29 if leap else 28
    return 30 if month in (4, 6, 9, 11) else 31

def _days_from_civil(year: int, month: int, day: int) -> int:
    y = year - (1 if month <= 2 else 0)
    era = (y if y >= 0 else y - 399) // 400
    year_of_era = y - era * 400
    day_of_year = (153 * (month + (-3 if month > 2 else 9)) + 2) // 5 + day - 1
    day_of_era = year_of_era * 365 + year_of_era // 4 - year_of_era // 100 + day_of_year
    return era * 146097 + day_of_era - 719468
from dataclasses import dataclass
import genlayer as gl
from genlayer.types import *
STATE_OPEN = 'open'
STATE_CLAIMED = 'claimed'

@gl.storage.allow
@dataclass
class Fund:
    goal_id: str
    payee: Address
    total: u256
    backers: u256
    state: str
    claimed_at: str

class Pot(gl.contract.Contract):
    goal: Address
    watch: Address
    funds: gl.storage.TreeMap[str, Fund]
    pledges: gl.storage.TreeMap[str, u256]
    fund_ids: gl.storage.DynArray[str]
    committed: u256

    def __init__(self, goal: str, watch: str):
        self.goal = _address(goal)
        self.watch = _address(watch)
        self.committed = 0

    @gl.public.write.payable
    def pledge(self, goal_id: str) -> dict:
        key = goal_id.strip().lower()
        amount = int(gl.message.value)
        if amount <= 0:
            raise gl.vm.UserError('send your pledge with this call')
        target = self._target(key)
        now = epoch_seconds(_stamp())
        if now is None:
            raise gl.vm.UserError('the clock could not be read')
        if now > int(str(target['deadline'])):
            raise gl.vm.UserError('the deadline has passed')
        status = self._status(key)
        if bool(status['shipped']):
            raise gl.vm.UserError('that release has already shipped; the pot is decided')
        if key not in self.funds:
            self.funds[key] = Fund(goal_id=key, payee=_address(target['payee']), total=0, backers=0, state=STATE_OPEN, claimed_at='')
            self.fund_ids.append(key)
        fund = self.funds[key]
        slot = key + '|' + gl.message.sender_address.as_hex.lower()
        before = int(self.pledges[slot]) if slot in self.pledges else 0
        if before == 0:
            fund.backers = fund.backers + 1
        self.pledges[slot] = before + amount
        fund.total = fund.total + amount
        self.funds[key] = fund
        self.committed = self.committed + amount
        return _as_dict(key, fund)

    @gl.public.write
    def claim(self, goal_id: str) -> dict:
        key = goal_id.strip().lower()
        fund = self._open(key)
        status = self._status(key)
        if not bool(status['in_time']):
            raise gl.vm.UserError('the release has not been seen in time')
        total = int(fund.total)
        fund.state = STATE_CLAIMED
        fund.claimed_at = _stamp()
        self.funds[key] = fund
        self.committed = self.committed - total
        _pay(fund.payee, total)
        return _as_dict(key, fund)

    @gl.public.write
    def refund(self, goal_id: str) -> dict:
        key = goal_id.strip().lower()
        fund = self._open(key)
        target = self._target(key)
        now = epoch_seconds(_stamp())
        if now is None:
            raise gl.vm.UserError('the clock could not be read')
        if now <= int(str(target['deadline'])):
            raise gl.vm.UserError('the deadline has not passed yet')
        status = self._status(key)
        if bool(status['in_time']):
            raise gl.vm.UserError('the release was seen in time, so the pot belongs to the payee')
        backer = gl.message.sender_address
        slot = key + '|' + backer.as_hex.lower()
        owed = int(self.pledges[slot]) if slot in self.pledges else 0
        if owed <= 0:
            raise gl.vm.UserError('you have nothing pledged to this goal')
        self.pledges[slot] = 0
        fund.total = fund.total - owed
        self.funds[key] = fund
        self.committed = self.committed - owed
        _pay(backer, owed)
        return {**_as_dict(key, fund), 'refunded': str(owed), 'to': backer.as_hex}

    @gl.public.view
    def get_fund(self, goal_id: str) -> dict:
        key = goal_id.strip().lower()
        if key not in self.funds:
            raise gl.vm.UserError('nobody has pledged to ' + key)
        return _as_dict(key, self.funds[key])

    @gl.public.view
    def pledged(self, goal_id: str, backer: str) -> str:
        slot = goal_id.strip().lower() + '|' + _address(backer).as_hex.lower()
        return str(self.pledges[slot]) if slot in self.pledges else '0'

    @gl.public.view
    def fund_list(self) -> list:
        return [f for f in self.fund_ids]

    @gl.public.view
    def reserves(self) -> dict:
        return {'committed': str(self.committed)}

    @gl.public.view
    def settings(self) -> dict:
        return {'goal': self.goal.as_hex, 'watch': self.watch.as_hex}

    def _target(self, key: str) -> dict:
        target = gl.contract.get_at(self.goal).view().get(key)
        if str(target['goal_id']).lower() != key:
            raise gl.vm.UserError('those terms are about a different goal')
        return target

    def _status(self, key: str) -> dict:
        status = gl.contract.get_at(self.watch).view().status(key)
        if str(status['goal_id']).lower() != key:
            raise gl.vm.UserError('that status is about a different goal')
        return status

    def _open(self, key: str) -> Fund:
        if key not in self.funds:
            raise gl.vm.UserError('nobody has pledged to ' + key)
        fund = self.funds[key]
        if fund.state != STATE_OPEN:
            raise gl.vm.UserError('that pot is already ' + fund.state)
        return fund

def _stamp() -> str:
    return str(gl.message.raw['datetime'])

def _address(value) -> Address:
    if hasattr(value, 'as_hex'):
        return value
    return Address(str(value).strip())

@gl.evm.contract_interface
class _Wallet:

    class View:
        pass

    class Write:
        pass

def _pay(to: Address, amount: int) -> None:
    _Wallet(to).emit_transfer(value=amount)

def _as_dict(key: str, fund: Fund) -> dict:
    return {'goal_id': key, 'payee': fund.payee.as_hex, 'total': str(fund.total), 'backers': str(fund.backers), 'state': fund.state, 'claimed_at': fund.claimed_at}
